const root = document.documentElement;
const languageSwitch = document.querySelector(".language-switch");
const languageCurrent = document.querySelector(".language-current");
const menuToggle = document.querySelector(".menu-toggle");
const nav = document.querySelector(".main-nav");

function setLanguage(language) {
  const dictionary = translations[language];
  const isArabic = language === "ar";

  root.lang = language;
  root.dir = isArabic ? "rtl" : "ltr";
  document.title = isArabic
    ? "Last Minute | وسيط التوريد المرن للفعاليات"
    : "Last Minute | Flexible Sourcing for Events";

  document.querySelectorAll("[data-i18n]").forEach((element) => {
    const key = element.dataset.i18n;
    if (dictionary[key]) element.textContent = dictionary[key];
  });

  document.querySelectorAll("[data-i18n-aria]").forEach((element) => {
    const key = element.dataset.i18nAria;
    if (dictionary[key]) element.setAttribute("aria-label", dictionary[key]);
  });

  document.querySelectorAll("[data-i18n-alt]").forEach((element) => {
    const key = element.dataset.i18nAlt;
    if (dictionary[key]) element.setAttribute("alt", dictionary[key]);
  });

  languageCurrent.textContent = isArabic ? "EN" : "ع";
  localStorage.setItem("last-minute-language", language);
}

languageSwitch.addEventListener("click", () => {
  setLanguage(root.lang === "ar" ? "en" : "ar");
});

menuToggle.addEventListener("click", () => {
  const expanded = menuToggle.getAttribute("aria-expanded") === "true";
  menuToggle.setAttribute("aria-expanded", String(!expanded));
  nav.classList.toggle("open", !expanded);
  document.body.classList.toggle("menu-open", !expanded);
});

nav.addEventListener("click", (event) => {
  if (!event.target.closest("a")) return;
  menuToggle.setAttribute("aria-expanded", "false");
  nav.classList.remove("open");
  document.body.classList.remove("menu-open");
});

setLanguage(localStorage.getItem("last-minute-language") === "en" ? "en" : "ar");
